def flatten(config: dict, sep: str = ".") -> dict:
    """
    Flattens a nested dictionary into a single-level dictionary.

    - Nested dicts are joined by the 'sep' argument.
    - Lists are flattened using [index] notation.
    - Empty dicts and empty lists are preserved as leaf values.
    - The input dictionary is not modified.
    """
    # Special case: Only flatten({}) itself is {}
    if not config:
        return {}

    flat_dict = {}

    def _recurse(current_obj, path: str):
        if isinstance(current_obj, dict):
            if not current_obj:
                # Empty dict is a leaf value
                flat_dict[path] = current_obj
            else:
                for key, value in current_obj.items():
                    # Join keys with the separator
                    new_key = f"{path}{sep}{key}" if path else key
                    _recurse(value, new_key)
        elif isinstance(current_obj, list):
            if not current_obj:
                # Empty list is a leaf value
                flat_dict[path] = current_obj
            else:
                for i, value in enumerate(current_obj):
                    # Append list index in brackets
                    new_key = f"{path}[{i}]"
                    _recurse(value, new_key)
        else:
            # Base case: value is not a dict or a list (leaf)
            flat_dict[path] = current_obj

    # Iterate through the top-level keys to start the recursion
    for key, value in config.items():
        _recurse(value, key)

    return flat_dict
